public class SmartEmbeddingCache
{
    private readonly IRedisClient _redis;
    private readonly IEmbeddingService _embedding;
    private readonly ILogger _logger;
    private const double SIMILARITY_THRESHOLD = 0.92;
    private const int CACHE_TTL_HOURS = 168;

    public async Task<float[]> GenerateOrGetCachedAsync(string text, string modelParams, CancellationToken ct = default)
    {
        // Content hash ensures identical text gets same embedding
        var contentHash = Sha256(text.Trim().ToLowerInvariant());
        var cacheKey = $"emb:{modelParams}:{contentHash}";

        var cached = await _redis.GetAsync(cacheKey);
        if (cached != null)
        {
            _logger.LogDebug("Cache HIT for {CacheKey}", cacheKey);
            return JsonSerializer.Deserialize<float[]>(cached);
        }

        _logger.LogDebug("Cache MISS for {CacheKey}, generating embedding", cacheKey);

        // Generate embedding from model
        var embedding = await _embedding.GenerateAsync(text, ct);

        // Store with expiration and metadata
        var cacheEntry = new EmbeddingCacheEntry
        {
            ContentHash = contentHash,
            TextPreview = text.Substring(0, Math.Min(100, text.Length)),
            GeneratedAt = DateTime.UtcNow,
            Embedding = embedding
        };

        await _redis.SetAsync(cacheKey, JsonSerializer.Serialize(cacheEntry),
            TimeSpan.FromHours(CACHE_TTL_HOURS));

        return embedding;
    }

    // Bulk invalidate when a document changes
    public async Task InvalidateDocumentAsync(string documentId, CancellationToken ct = default)
    {
        // Remove all cache entries referencing this document
        // In Redis: use tag-based invalidation or scan-and-delete
        await _redis.RemoveByPatternAsync($"emb:*:{Sha256(documentId)}:*", ct);
    }
}

public class TieredEmbeddingCache
{
    private readonly IMemoryCache _memoryCache;
    private readonly IDistributedCache _redisCache;
    private readonly ConcurrentDictionary<string, SemaphoreSlim> _locks = new();
    private static readonly TimeSpan MemoryTtl = TimeSpan.FromHours(1);
    private static readonly TimeSpan RedisTtl = TimeSpan.FromDays(7);

    public async Task<float[]> GetEmbeddingAsync(string text, CancellationToken ct = default)
    {
        var cacheKey = $"emb:{Sha256(text)}";

        // L1: Try in-memory cache (microsecond latency)
        if (_memoryCache.TryGetValue<float[]>(cacheKey, out var memoryHit))
            return memoryHit;

        // L2: Try Redis cache (sub-millisecond)
        var redisHit = await _redisCache.GetAsync<float[]>(cacheKey, ct);
        if (redisHit != null)
        {
            _memoryCache.Set(cacheKey, redisHit, MemoryTtl);
            return redisHit;
        }

        // Cache miss: generate with singleton lock to prevent thundering herd
        var semaphore = _locks.GetOrAdd(cacheKey, _ => new SemaphoreSlim(1, 1));
        await semaphore.WaitAsync(ct);

        try
        {
            // Double-check after acquiring lock
            if (_memoryCache.TryGetValue<float[]>(cacheKey, out var cached))
                return cached;

            var embedding = await GenerateEmbeddingAsync(text, ct);
            await _redisCache.SetAsync(cacheKey, embedding, RedisTtl, ct);
            _memoryCache.Set(cacheKey, embedding, MemoryTtl);
            return embedding;
        }
        finally
        {
            semaphore.Release();
            _locks.TryRemove(cacheKey, out _);
        }
    }
}
